sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_scale;
uniform float amzp_angle;
uniform float2 amzp_position;
uniform float2 amzp_stretch;
uniform float amzp_alpha;
uniform float amzp_blendMode;
uniform float amzp_alphaComp;
layout(color) uniform half4 amzp_color;
layout(color) uniform half4 amzp_color2;
uniform float amzp_line_thickness;
uniform float amzp_bar_width;
uniform float amzp_dot_size;
uniform float amzp_roundness;
uniform float amzp_glow;
uniform float amzp_glow_size;
uniform float amzp_show_line;
uniform float amzp_show_dots;
uniform float amzp_baseline_y;
uniform float amzp_left_margin;
uniform float amzp_bar_count;
uniform float amzp_bar_max_height;
uniform float amzp_direction;
uniform float amzp_bass_center;
uniform float amzp_audio_level;
uniform float amzp_bass;
uniform float amzp_mid;
uniform float amzp_high;
uniform float amzp_band_mix;
uniform float amzp_reactivity;
uniform float amzp_jitter;
uniform float amzp_motion;
uniform float amzp_speed;
uniform float amzp_seed;
    float2 nmRot(float2 q, float a) { float c = cos(a), s = sin(a); return float2(c * q.x - s * q.y, s * q.x + c * q.y); }
    float2 nmStd(float2 p, float pxs) {
        float z = max(amzp_scale * 2.0, 0.002);
        p -= amzp_position * pxs;
        p = nmRot(p, -radians(amzp_angle));
        return p / (z * max(amzp_stretch, float2(0.01)));
    }
    float4 nmBlend(float4 tex, float4 fx) {
        float4 f = clamp(fx, 0.0, 1.0) * clamp(amzp_alpha, 0.0, 1.0);
        float4 b = tex * clamp(amzp_alphaComp, 0.0, 1.0);
        float4 o;
        if (int(amzp_blendMode) == 0) o = f;
        else if (int(amzp_blendMode) == 1) o = float4(b.rgb * (f.rgb + (1.0 - f.a)), b.a);
        else if (int(amzp_blendMode) == 2) o = float4(b.rgb + f.rgb - b.rgb * f.rgb, b.a + f.a - b.a * f.a);
        else o = f + b * (1.0 - f.a);
        o = clamp(o, 0.0, 1.0);
        return float4(min(o.rgb, float3(o.a)), o.a);
    }
    float hash11(float n) { return fract(sin(n * 127.1 + 311.7) * 43758.5453); }
    float bandAt(float x) {
        float wb = 1.0 - smoothstep(0.0, 0.45, x);
        float wh = smoothstep(0.55, 1.0, x);
        float wm = max(0.0, 1.0 - wb - wh);
        return clamp(amzp_bass, 0.0, 1.0) * wb + clamp(amzp_mid, 0.0, 1.0) * wm + clamp(amzp_high, 0.0, 1.0) * wh;
    }
    float bandAmp(float i, float N) {
        float g = (i + 0.5) / N;
        float x = (amzp_bass_center>0.5) ? abs(g * 2.0 - 1.0) : g;
        float lv = mix(clamp(amzp_audio_level, 0.0, 1.0), bandAt(x), clamp(amzp_band_mix, 0.0, 1.0));
        float base = pow(lv, max(amzp_reactivity, 0.1));
        float rnd = (hash11(i + amzp_seed) * 2.0 - 1.0) * amzp_jitter;
        float wob = 0.5 + 0.5 * sin(time * (2.5 * amzp_speed) + i * 0.9);
        float env = 0.85 - 0.35 * abs((i / max(N - 1.0, 1.0)) * 2.0 - 1.0);
        return clamp(base * env * (mix(1.0, 0.6 + 0.8 * wob, clamp(amzp_motion, 0.0, 1.0)) + rnd), 0.0, 1.0);
    }
    float sdb(float2 q, float r) {
        q += r;
        return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - r;
    }
    float barD(float2 P, float i, float N, float margin, float slot, float by, float Hm, float hw, out float hgt) {
        float amp = bandAmp(i, N);
        float h = Hm * amp;
        hgt = h;
        float cx = margin + (i + 0.5) * slot;
        float cy, hh;
        if (int(amzp_direction) == 1) { cy = by + h * 0.5; hh = h * 0.5; }
        else if (int(amzp_direction) == 2) { cy = by - h * 0.5; hh = h * 0.5; }
        else { cy = by; hh = h; }
        float r = clamp(amzp_roundness, 0.0, 1.0) * min(hw, hh);
        return sdb(float2(abs(P.x - cx) - hw, abs(P.y - cy) - hh), r);
    }
    void amzRender() {
        float2 S = screen.zw;
        float4 lay = amzTexture(0, amzScreenNorm());
        float2 sc = amzScreenNorm() * S - 0.5 * S;
        sc = nmStd(float2(sc.x, -sc.y), S.x / max(screen.zw.x, 1.0));
        float2 P = float2(sc.x, -sc.y) + 0.5 * S;
        float margin = clamp(amzp_left_margin, 0.0, 0.49) * S.x;
        float N = max(floor(amzp_bar_count + 0.5), 1.0);
        float usable = max(S.x - 2.0 * margin, 1.0);
        float slot = usable / N;
        float by = amzp_baseline_y * S.y;
        float Hm = max(amzp_bar_max_height, 0.0) * S.y;
        float hw = max(amzp_bar_width * 0.5 * S.x, 0.5);
        float gs = max(amzp_glow_size, 1.0);
        float reach = amzp_glow > 0.0 ? gs * 4.0 : 2.0;
        float xIn = (P.x - margin) / usable;
        if (P.x < margin - reach || P.x > S.x - margin + reach) { amzOutput = nmBlend(lay, float4(0.0)); return; }
        float i0 = clamp(floor(xIn * N), 0.0, N - 1.0);
        float cov = 0.0, dmin = 1e6, t = 0.0;
        for (int k = -1; k <= 1; k++) {
            float i = i0 + float(k);
            if (i < 0.0 || i > N - 1.0) continue;
            float hgt;
            float d = barD(P, i, N, margin, slot, by, Hm, hw, hgt);
            if (d < dmin) {
                dmin = d;
                t = clamp(abs(P.y - by) / max(Hm, 1.0), 0.0, 1.0);
            }
            cov = max(cov, clamp(0.5 - d, 0.0, 1.0));
        }
        if ((amzp_show_line>0.5) && amzp_line_thickness > 0.0) {
            float lt = max(amzp_line_thickness * 0.5 * S.y, 0.25);
            float dl = sdb(float2(abs(P.x - S.x * 0.5) - usable * 0.5, abs(P.y - by) - lt), 0.0);
            cov = max(cov, clamp(0.5 - dl, 0.0, 1.0));
            dmin = min(dmin, dl);
        }
        if ((amzp_show_dots>0.5) && amzp_dot_size > 0.0 && N > 1.0) {
            float kb = clamp(floor((P.x - margin) / slot + 0.5), 1.0, N - 1.0);
            float dd = length(float2(P.x - (margin + kb * slot), P.y - by)) - amzp_dot_size * S.x;
            cov = max(cov, clamp(0.5 - dd, 0.0, 1.0));
            dmin = min(dmin, dd);
        }
        float3 col = mix(amzp_color.rgb, amzp_color2.rgb, t);
        float a = cov;
        float3 rgb = col * a;
        if (amzp_glow > 0.0) {
            float g = exp(-max(dmin, 0.0) / gs) * amzp_glow * 0.5 * (1.0 - cov);
            rgb += col * g;
            a = max(a, clamp(g, 0.0, 1.0));
        }
        rgb = min(rgb, float3(a));
        amzOutput = nmBlend(lay, float4(rgb, a));
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
